<?php require 'config.php'; role(['admin','kasir']); header('Content-Type: application/json'); try{$items=json_decode($_POST['items']??'[]',true);$pay=(int)$_POST['pay_amount'];if(!$items)throw new Exception('Keranjang kosong');$conn->begin_transaction();$total=0;$rows=[];foreach($items as $i){$id=(int)$i['id'];$qty=(int)$i['qty'];$q=$conn->query("SELECT * FROM menus WHERE id=$id FOR UPDATE");$m=$q->fetch_assoc();if(!$m||$m['stock']<$qty)throw new Exception('Stok tidak mencukupi: '.($m['name']??''));$sub=$m['price']*$qty;$total+=$sub;$rows[]=[$m,$qty,$sub];}if($pay<$total)throw new Exception('Pembayaran kurang.');$invoice='INV-'.date('YmdHis').'-'.strtoupper(substr(md5(uniqid()),0,4));$uid=(int)$_SESSION['user']['id'];$table=$_POST['table_number']??null;$type=$_POST['order_type']??'dine_in';$payment=$_POST['payment_method']??'cash';$change=$pay-$total;$s=$conn->prepare("INSERT INTO transactions(invoice_code,user_id,total_amount,pay_amount,change_amount,table_number,order_type,payment_method) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('siiiisss',$invoice,$uid,$total,$pay,$change,$table,$type,$payment);$s->execute();$tid=$conn->insert_id;$d=$conn->prepare("INSERT INTO transaction_details(transaction_id,menu_id,qty,subtotal) VALUES(?,?,?,?)");foreach($rows as [$m,$qty,$sub]){$mid=$m['id'];$d->bind_param('iiii',$tid,$mid,$qty,$sub);$d->execute();$conn->query("UPDATE menus SET stock=stock-$qty WHERE id=$mid");}$conn->commit();echo json_encode(['success'=>true,'id'=>$tid]);}catch(Throwable $e){$conn->rollback();http_response_code(422);echo json_encode(['success'=>false,'message'=>$e->getMessage()]);}?>